"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82523"],{6646(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.uf_do_municipio_invalida","status":422,"titulo":"Os munic\xedpios da UF citam um campo de UF do Geo"},"descricao":{"codigo":"uniplus.item_formulario.uf_do_municipio_invalida","requisitos":["UNI-REQ-0145"],"oQueAconteceu":["A restri\xe7\xe3o `MUNICIPIOS_DA_UF` de um campo de munic\xedpio, em `restricoes`, filtra os munic\xedpios pela UF respondida antes (UNI-REQ-0145). O fato citado em `fatos` n\xe3o serve de UF: n\xe3o existe no cat\xe1logo, n\xe3o tem como fonte de valores as UFs do Geo, ou \xe9 de resposta m\xfaltipla. A mensagem \xe9 \\"Os munic\xedpios da UF citam um campo de UF de resposta \xfanica, com as UFs do Geo.\\", e a recusa leva o c\xf3digo do fato citado. A restri\xe7\xe3o s\xf3 \xe9 conferida quando cabe no tipo do campo.","A recusa vem na lista `errors` da resposta, com `field` igual a `restricoes[k].fatos`, precedido de `itens[i].` ou de `grupos[g].subitens[j].`; nos modelos de formul\xe1rio come\xe7a por `conteudo.`, e na aplica\xe7\xe3o de modelo por `modelo.`, com a posi\xe7\xe3o do item no modelo. Na publica\xe7\xe3o inicial e na retifica\xe7\xe3o em ato \xfanico, os itens gravados s\xe3o reconferidos contra o cat\xe1logo de hoje, e o `field` come\xe7a por `formularios[FINALIDADE]`, como em `formularios[INSCRICAO].itens[0].restricoes[0].fatos`; a mensagem ganha o final \\"Item \'`{r\xf3tulo\\\\}`\' (fato \'`{c\xf3digo\\\\}`\'). Regrave o item no formul\xe1rio do processo.\\". O fato que uma vers\xe3o publicada j\xe1 coletou n\xe3o \xe9 reconferido. Nada \xe9 gravado.","Na atualiza\xe7\xe3o de um modelo, um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Cite em `fatos` o fato da UF coletada por um campo anterior do formul\xe1rio, de resposta \xfanica e de fonte UF do Geo. Consulte o cat\xe1logo de fatos do candidato no m\xf3dulo Configura\xe7\xe3o para escolher o fato."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio","Aplica\xe7\xe3o de modelo de formul\xe1rio","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);